let __v_2221 = { let mut __items_2222 = Vec::new(); let __v_2223 = pyrt::literals::decode("{\"$tuple\":[\"atm\",{\"$tuple\":[\"atm mean\",\"atm stand for\",\"atm short for\",\"atm\",\"atms\"]},\"ATM stands for automated teller machine, which is the cash machine in the wall. The useful part is not in the letters: the machine asks your bank before it counts out anything, so a card that works in the shop can still be refused here if the answer is no.\"]}")?; __items_2222.push(__v_2223); let __v_2224 = pyrt::literals::decode("{\"$tuple\":[\"cv\",{\"$tuple\":[\"cv\",\"cvs\",\"curriculum vitae\"]},\"CV stands for curriculum vitae, Latin for the course of your life, and the name oversells what should be a page or two: the last two jobs with what you actually did in them, dates, qualifications, and a line at the top saying what you are after. Gaps are fine on a CV so long as the dates are honest.\"]}")?; __items_2222.push(__v_2224); let __v_2225 = pyrt::literals::decode("{\"$tuple\":[\"ai\",{\"$tuple\":[\"ai\"]},\"AI stands for artificial intelligence, and in use it means software that finds the pattern in a lot of examples instead of being told the rule. That is why it is good at sorting photographs and writing a first draft, and why it can state a wrong fact as confidently as a right one - the answer is fluent whether or not it is true.\"]}")?; __items_2222.push(__v_2225); let __v_2226 = pyrt::literals::decode("{\"$tuple\":[\"hr\",{\"$tuple\":[\"hr\",\"human resources\"]},\"HR stands for human resources: the department that holds the contracts, the pay, the holidays and the complaints. The order that works for a problem at work is your manager first, their manager if that goes nowhere, and HR in writing after that, because HR's job is the company's side of the paperwork.\"]}")?; __items_2222.push(__v_2226); let __v_2227 = pyrt::literals::decode("{\"$tuple\":[\"ceo\",{\"$tuple\":[\"ceo\"]},\"CEO stands for chief executive officer: the person who runs the company day to day and answers to the board. Their name is on the big decisions, not on the ordinary complaint - a refund or a wrong bill is still the customer service desk's job.\"]}")?; __items_2222.push(__v_2227); let __v_2228 = pyrt::literals::decode("{\"$tuple\":[\"faq\",{\"$tuple\":[\"faq\",\"faqs\"]},\"FAQ stands for frequently asked questions: the page, usually at the foot of a website, where the thing you are about to write in has already been answered. Search that page for one distinctive word of your problem before you write, because the answer is often there in two lines and the form takes days.\"]}")?; __items_2222.push(__v_2228); let __v_2229 = pyrt::literals::decode("{\"$tuple\":[\"cbt\",{\"$tuple\":[\"cbt\"]},\"CBT stands for cognitive behavioural therapy: a short talking treatment that works on the loop between what you think, what you do and how you feel, usually six to twenty weekly sessions with something to try between them. It is what the NHS offers first for anxiety and low mood, and in England you can refer yourself to it without seeing a GP.\"]}")?; __items_2222.push(__v_2229); let __v_2230 = pyrt::literals::decode("{\"$tuple\":[\"ae\",{\"$tuple\":[\"a and e\",\"a e\",\"a&e\",\"accident and emergency\"]},\"A&E stands for accident and emergency, the hospital department for what cannot wait: chest pain, bad breathlessness, a bone through the skin, a head injury with vomiting or a collapse. If you are unsure whether to go, NHS 111 will say, and it is worth the call because A&E is the slowest place to be seen for something a pharmacist or a GP could handle.\"]}")?; __items_2222.push(__v_2230); let __v_2231 = pyrt::literals::decode("{\"$tuple\":[\"sos\",{\"$tuple\":[\"sos\"]},\"SOS does not stand for anything: it was picked in 1905 because three dots, three dashes and three dots is unmistakable in Morse and spells no word that could be misread. It is not an abbreviation, so there is nothing hidden in the letters.\"]}")?; __items_2222.push(__v_2231); let __v_2232 = pyrt::literals::decode("{\"$tuple\":[\"ppi\",{\"$tuple\":[\"ppi\",\"payment protection insurance\"]},\"PPI stands for payment protection insurance: a policy sold beside a loan or a credit card to cover the repayments if you lost your job or fell ill. Many were mis-sold, and the free route was a complaint to the lender that sold it - the deadline for new complaints passed in 2019, so a policy sold since then is the one worth reading the terms of.\"]}")?; __items_2222.push(__v_2232); let __v_2233 = pyrt::literals::decode("{\"$tuple\":[\"dwp\",{\"$tuple\":[\"dwp\",\"department for work and pensions\"]},\"DWP stands for the Department for Work and Pensions: the department that pays Universal Credit, the state pension, PIP and jobseeker's payments, and runs the jobcentre. A letter from it with a date on it needs an answer by that date even if the answer is 'I need more time', because a missed deadline restarts the claim rather than pausing it.\"]}")?; __items_2222.push(__v_2233); let __v_2234 = pyrt::literals::decode("{\"$tuple\":[\"hmo\",{\"$tuple\":[\"hmo\",\"house in multiple occupation\"]},\"HMO stands for house in multiple occupation: a house or flat let to three or more people who are not one family and who share a kitchen or a bathroom. A larger one needs a licence from the council, and the council's private renting team is who to ring about fire doors, alarms or overcrowding - not the landlord's own answer.\"]}")?; __items_2222.push(__v_2234); let __v_2235 = pyrt::literals::decode("{\"$tuple\":[\"nsi\",{\"$tuple\":[\"ns&i\",\"ns and i\",\"national savings\"]},\"NS&I stands for National Savings and Investments: the government's own savings bank, where Premium Bonds and Index-linked Savings Certificates come from. The money is backed by the Treasury instead of a commercial bank, so the compensation limit quoted for banks does not apply to it, and the rates are usually ordinary rather than the best on the market.\"]}")?; __items_2222.push(__v_2235); let __v_2236 = pyrt::literals::decode("{\"$tuple\":[\"etf\",{\"$tuple\":[\"etf\",\"etfs\"]},\"ETF stands for exchange-traded fund: a basket of shares that is bought and sold like a single share, so one purchase spreads the money over hundreds of companies. The charge is usually a fraction of a percent a year, and over decades that costs less than picking shares yourself - which is the whole argument for it.\"]}")?; __items_2222.push(__v_2236); let __v_2237 = pyrt::literals::decode("{\"$tuple\":[\"isa\",{\"$tuple\":[\"isa\",\"isas\"]},\"ISA stands for individual savings account: a wrapper rather than a product, so a cash ISA and a stocks-and-shares ISA are both ISAs and what is inside them is free of UK tax on interest and gains. The allowance is per person, per tax year, and it resets in April whether or not you used the last one.\"]}")?; __items_2222.push(__v_2237); let __v_2238 = pyrt::literals::decode("{\"$tuple\":[\"gp\",{\"$tuple\":[\"gp\",\"gps surgery\",\"general practitioner\"]},\"GP stands for general practitioner: the family doctor who sees you first and refers you on to a specialist. You can change practice without giving a reason, and the same-day slots usually go to the people who ring at opening time, so ring rather than walk in.\"]}")?; __items_2222.push(__v_2238); let __v_2239 = { let mut __items_2240 = Vec::new(); let __v_2241 = Value::from("kg"); __items_2240.push(__v_2241); let __v_2242 = { let mut __items_2243 = Vec::new(); let __v_2244 = Value::from("kg"); __items_2243.push(__v_2244); let __v_2245 = Value::from("kgs"); __items_2243.push(__v_2245); Value::tuple(__items_2243) }; __items_2240.push(__v_2242); let __v_2246 = Value::from("kg is short for kilogram: 1,000 grams, and about 2.2 pounds. A stone is 6.35 kg, which is why a person's weight in kilos is a bigger number than the same weight in pounds."); __items_2240.push(__v_2246); Value::tuple(__items_2240) }; __items_2222.push(__v_2239); let __v_2247 = pyrt::literals::decode("{\"$tuple\":[\"mg\",{\"$tuple\":[\"mg\",\"mgs\"]},\"mg is short for milligram: a thousandth of a gram, so 1,000 mg is 1 g. A 500 mg paracetamol tablet is half a gram, and the dose on the box is written in these units because the useful amount is too small to weigh in grams.\"]}")?; __items_2222.push(__v_2247); let __v_2248 = { let mut __items_2249 = Vec::new(); let __v_2250 = Value::from("mph"); __items_2249.push(__v_2250); let __v_2251 = { let mut __items_2252 = Vec::new(); let __v_2253 = Value::from("mph"); __items_2252.push(__v_2253); Value::tuple(__items_2252) }; __items_2249.push(__v_2251); let __v_2254 = Value::from("mph is short for miles per hour: how many miles the thing would cover in an hour at that speed. 30 mph is about 48 km/h, which is why a British speed limit and a European one are never the same number."); __items_2249.push(__v_2254); Value::tuple(__items_2249) }; __items_2222.push(__v_2248); let __v_2255 = { let mut __items_2256 = Vec::new(); let __v_2257 = Value::from("kph"); __items_2256.push(__v_2257); let __v_2258 = { let mut __items_2259 = Vec::new(); let __v_2260 = Value::from("kph"); __items_2259.push(__v_2260); let __v_2261 = Value::from("kmh"); __items_2259.push(__v_2261); let __v_2262 = Value::from("km/h"); __items_2259.push(__v_2262); Value::tuple(__items_2259) }; __items_2256.push(__v_2258); let __v_2263 = Value::from("kph is short for kilometres per hour, the unit on every speedometer outside Britain and the United States. 100 kph is about 62 mph, and 50 kph in town is about 31 mph."); __items_2256.push(__v_2263); Value::tuple(__items_2256) }; __items_2222.push(__v_2255); let __v_2264 = pyrt::literals::decode("{\"$tuple\":[\"tbsp\",{\"$tuple\":[\"tbsp\",\"tbsps\",\"tablespoon\",\"tablespoons\"]},\"tbsp is short for tablespoon: 15 ml in a British, American or Australian recipe, and three level teaspoons. A heaped tablespoon of flour or sugar weighs more than 15 g, so level it off unless the recipe says heaped.\"]}")?; __items_2222.push(__v_2264); let __v_2265 = pyrt::literals::decode("{\"$tuple\":[\"tsp\",{\"$tuple\":[\"tsp\",\"tsps\",\"teaspoon\",\"teaspoons\"]},\"tsp is short for teaspoon: 5 ml, and a third of a tablespoon. A level teaspoon of salt is about 6 g and of sugar about 4 g, which is why a spoon is a safe measure for salt and a rough one for anything you are weighing.\"]}")?; __items_2222.push(__v_2265); let __v_2266 = pyrt::literals::decode("{\"$tuple\":[\"oled\",{\"$tuple\":[\"oled mean\",\"oled stand for\",\"oled\",\"oled tv\",\"oled screen\"]},\"OLED stands for organic light-emitting diode: every pixel makes its own light, which is why the blacks are truly black and the panel is thin enough to bend. The organic layer dims as it is used, so a bright static logo can leave a faint mark after years, and that is what the extra price over an LCD buys and costs.\"]}")?; __items_2222.push(__v_2266); let __v_2267 = pyrt::literals::decode("{\"$tuple\":[\"hpv\",{\"$tuple\":[\"hpv\",\"human papillomavirus\"]},\"HPV stands for human papillomavirus: a very common group of viruses passed on by skin-to-skin contact, and most infections clear on their own. The types that cause most cervical cancer are the ones the NHS vaccine guards against, offered at 12 to 13, and the smear test finds the changes years before they become cancer.\"]}")?; __items_2222.push(__v_2267); let __v_2268 = pyrt::literals::decode("{\"$tuple\":[\"pms\",{\"$tuple\":[\"pms\",\"premenstrual syndrome\",\"pre menstrual syndrome\"]},\"PMS stands for premenstrual syndrome: the mix of low mood, bloating, tender breasts and tiredness in the week or two before a period, which lifts once it starts. It is common and treatable - regular exercise, less caffeine and the combined pill help some women - so see a GP if it is spoiling a week of every month.\"]}")?; __items_2222.push(__v_2268); let __v_2269 = pyrt::literals::decode("{\"$tuple\":[\"ibs\",{\"$tuple\":[\"ibs\",\"irritable bowel syndrome\"]},\"IBS stands for irritable bowel syndrome: cramping, bloating, wind and a change in how often you go, with nothing wrong with the gut itself. It is managed rather than cured - regular meals, enough fibre and water, less caffeine and alcohol - and a GP can rule out coeliac disease and check a change you have never had before.\"]}")?; __items_2222.push(__v_2269); let __v_2270 = pyrt::literals::decode("{\"$tuple\":[\"uti\",{\"$tuple\":[\"uti\",\"utis\",\"urinary tract infection\"]},\"UTI stands for urinary tract infection: bugs in the bladder that cause burning when you pee, going often and a dragging ache low down. Most clear in a day or two with plenty of water, a pharmacy can advise, and see a GP or ring 111 the same day with a fever, back pain, blood, or if you are pregnant, a man or a child.\"]}")?; __items_2222.push(__v_2270); let __v_2271 = pyrt::literals::decode("{\"$tuple\":[\"bmi\",{\"$tuple\":[\"bmi\",\"body mass index\"]},\"BMI stands for body mass index: weight in kilos divided by height in metres squared, with 18.5 to 24.9 called healthy for most adults. It is a rough measure - it cannot tell muscle from fat, so it reads high on a rugby player and low on some older people, which is why waist size is worth knowing too.\"]}")?; __items_2222.push(__v_2271); let __v_2272 = pyrt::literals::decode("{\"$tuple\":[\"ocd\",{\"$tuple\":[\"ocd\",\"obsessive compulsive disorder\"]},\"OCD stands for obsessive-compulsive disorder: unwanted, repeated thoughts that arrive on their own, and the rituals done to quieten them, like checking the hob or washing. It is common and treatable - talking therapy, usually CBT with exposure and response prevention, helps most people - so it is worth seeing a GP rather than putting up with it.\"]}")?; __items_2222.push(__v_2272); let __v_2273 = pyrt::literals::decode("{\"$tuple\":[\"ptsd\",{\"$tuple\":[\"ptsd\",\"post traumatic stress disorder\"]},\"PTSD stands for post-traumatic stress disorder: flashbacks, nightmares, jumpiness and avoiding places after a frightening event, still there a month on. It is not weakness and it is treatable - trauma-focused talking therapy such as CBT or EMDR helps most people - so ask a GP for a referral rather than waiting for it to pass.\"]}")?; __items_2222.push(__v_2273); let __v_2274 = pyrt::literals::decode("{\"$tuple\":[\"hrt\",{\"$tuple\":[\"hrt\",\"hormone replacement therapy\"]},\"HRT stands for hormone replacement therapy: oestrogen, usually with a progestogen, given to ease hot flushes, night sweats and mood swings of the menopause and to protect bone. It comes as tablets, patches or gel; for most women under 60 the risks are small, and a GP can talk through which type suits you.\"]}")?; __items_2222.push(__v_2274); let __v_2275 = { let mut __items_2276 = Vec::new(); let __v_2277 = Value::from("iud"); __items_2276.push(__v_2277); let __v_2278 = frame.load(rt, "COIL_NAMES")?; __items_2276.push(__v_2278); let __v_2279 = Value::from("IUD stands for intrauterine device: the small T-shaped coil a doctor or nurse fits into the womb, and it lasts five to ten years - a copper one five, the hormonal ones three to eight. Fitting takes a few minutes at a clinic or GP surgery, it is free on the NHS, and cramping for a day or two afterwards is usual. A copper one also works as emergency contraception up to five days after sex, the hormonal ones usually make periods lighter or stop them, and as long as you are over 16 you can ask for one without telling anyone."); __items_2276.push(__v_2279); Value::tuple(__items_2276) }; __items_2222.push(__v_2275); let __v_2280 = pyrt::literals::decode("{\"$tuple\":[\"sti\",{\"$tuple\":[\"sti\",\"stis\",\"sexually transmitted infection\"]},\"STI stands for sexually transmitted infection: an infection passed on during sex, such as chlamydia, gonorrhoea or HIV. Most have no symptoms, so a test is the only way to know, and testing is free and confidential at a sexual health clinic or by post - nearly all clear with a short course of antibiotics.\"]}")?; __items_2222.push(__v_2280); let __v_2281 = pyrt::literals::decode("{\"$tuple\":[\"ivf\",{\"$tuple\":[\"ivf\",\"in vitro fertilisation\",\"in vitro fertilization\"]},\"IVF stands for in vitro fertilisation: an egg is fertilised with sperm in a laboratory, and an embryo is put back into the womb. One cycle takes about four to six weeks, the NHS funds a set number depending on where you live and your age, and the chance of success falls steeply through the late thirties.\"]}")?; __items_2222.push(__v_2281); let __v_2282 = pyrt::literals::decode("{\"$tuple\":[\"pip\",{\"$tuple\":[\"pip\",\"pips\",\"personal independence payment\"]},\"PIP stands for Personal Independence Payment: the benefit for adults under state pension age who have extra costs from a long-term illness or disability, for getting around or for daily tasks. It is not means-tested, so savings and a job do not rule you out, and the decision rests on an assessment of what you can do, not on the diagnosis.\"]}")?; __items_2222.push(__v_2282); let __v_2283 = pyrt::literals::decode("{\"$tuple\":[\"paye\",{\"$tuple\":[\"paye\",\"pay as you earn\"]},\"PAYE stands for pay as you earn: your employer takes income tax and National Insurance out of each payslip and sends it to HMRC, so the tax is paid as you go rather than in one bill. Your tax code is what tells them how much to take, so check it on the payslip - a wrong code is the usual reason a wage comes out short.\"]}")?; __items_2222.push(__v_2283); let __v_2284 = pyrt::literals::decode("{\"$tuple\":[\"p45\",{\"$tuple\":[\"p45\",\"p45s\"]},\"A P45 is the form an employer gives you when you leave: the pay and tax so far that tax year and the code the next employer needs. Keep it, because the new job asks for it, and without one you can be put on an emergency code and overtaxed until it is sorted out.\"]}")?; __items_2222.push(__v_2284); let __v_2285 = pyrt::literals::decode("{\"$tuple\":[\"p60\",{\"$tuple\":[\"p60\",\"p60s\"]},\"A P60 is the one-page summary an employer gives you after 5 April: the pay, the tax paid and your tax code for the year just gone. Keep it, because a mortgage, a visa or a tax return can all ask for it, and it is the quickest proof of what you earned.\"]}")?; __items_2222.push(__v_2285); let __v_2286 = pyrt::literals::decode("{\"$tuple\":[\"hmrc\",{\"$tuple\":[\"hmrc\",\"hm revenue and customs\",\"revenue and customs\"]},\"HMRC stands for HM Revenue and Customs: the tax office, which deals with income tax, National Insurance, VAT and child benefit. It never asks for a password, a payment or a gift card by text or email - that message is a scam - and refunds, tax codes and self-assessment all go through your own account on gov.uk.\"]}")?; __items_2222.push(__v_2286); let __v_2287 = pyrt::literals::decode("{\"$tuple\":[\"apr\",{\"$tuple\":[\"apr\",\"annual percentage rate\"]},\"APR stands for annual percentage rate: the interest plus the fees on a loan or a card, worked out over a year, so it is the number to compare two offers on rather than the headline rate. A 0% offer is only free if the balance is cleared before the rate ends, and a card's APR applies to cash withdrawals from day one.\"]}")?; __items_2222.push(__v_2287); let __v_2288 = pyrt::literals::decode("{\"$tuple\":[\"rrp\",{\"$tuple\":[\"rrp\",\"recommended retail price\"]},\"RRP stands for recommended retail price: the price the maker suggests, not one a shop has to charge. Shops often sell below it, so a crossed-out RRP is a marketing figure - compare what you would actually pay elsewhere rather than the saving on the label.\"]}")?; __items_2222.push(__v_2288); let __v_2289 = pyrt::literals::decode("{\"$tuple\":[\"dbs\",{\"$tuple\":[\"dbs\",\"disclosure and barring service\",\"dbs check\"]},\"DBS stands for Disclosure and Barring Service: the checks that show a criminal record to an employer, for work with children, patients or vulnerable adults. A basic, standard or enhanced check is applied for by the employer, not by you, and the certificate goes to you so you can show it to whoever asks.\"]}")?; __items_2222.push(__v_2289); let __v_2290 = pyrt::literals::decode("{\"$tuple\":[\"lpa\",{\"$tuple\":[\"lpa\",\"lasting power of attorney\"]},\"LPA stands for lasting power of attorney: the legal document that lets someone you choose make decisions for you if you cannot - about money and property, or about health and care. It has to be registered with the Office of the Public Guardian while you still have the capacity to make it, and it costs £82 per document in England and Wales.\"]}")?; __items_2222.push(__v_2290); let __v_2291 = pyrt::literals::decode("{\"$tuple\":[\"ghic\",{\"$tuple\":[\"ghic\",\"global health insurance card\"]},\"GHIC stands for Global Health Insurance Card: the free card that gives you state-provided medical care in the EU on the same terms as a local, and it replaced the EHIC for new applications after Brexit. It does not cover private treatment or getting you home, so travel insurance is still the thing to buy.\"]}")?; __items_2222.push(__v_2291); let __v_2292 = pyrt::literals::decode("{\"$tuple\":[\"ehic\",{\"$tuple\":[\"ehic\",\"european health insurance card\"]},\"EHIC stands for European Health Insurance Card: the free card that gave state-provided medical care in the EU on the same terms as a local. New applications were replaced by the GHIC after Brexit, and an EHIC already issued still works until the date on it runs out.\"]}")?; __items_2222.push(__v_2292); let __v_2293 = pyrt::literals::decode("{\"$tuple\":[\"epc\",{\"$tuple\":[\"epc\",\"epcs\",\"energy performance certificate\"]},\"EPC stands for energy performance certificate: the A to G rating a home gets when it is sold or let, from how much it costs to heat and how well it holds the heat. A rented home has to reach band E, and a low rating is the best handle for asking the landlord for insulation or a newer boiler.\"]}")?; __items_2222.push(__v_2293); let __v_2294 = pyrt::literals::decode("{\"$tuple\":[\"vpn\",{\"$tuple\":[\"vpn\",\"vpns\",\"virtual private network\"]},\"VPN stands for virtual private network: it makes an encrypted tunnel between your device and a server elsewhere, so the owner of the wifi cannot see which sites you open. It is worth it on hotel and cafe wifi, but it does not make you anonymous - the VPN company can still see and log the traffic.\"]}")?; __items_2222.push(__v_2294); Value::tuple(__items_2222) };
